import{_ as s,o as a,c as t,ag as i}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/performance.md","filePath":"troubleshooting/performance.md","lastUpdated":1772297611000}'),n={name:"troubleshooting/performance.md"};function o(r,e,l,p,d,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>This page covers performance-related issues with NectoProxy and how to resolve them.</p><h2 id="slow-web-ui" tabindex="-1">Slow Web UI <a class="header-anchor" href="#slow-web-ui" aria-label="Permalink to &quot;Slow Web UI&quot;">​</a></h2><p><strong>Symptom:</strong> The NectoProxy Web UI feels sluggish, scrolling is choppy, or the interface is unresponsive.</p><h3 id="too-many-traffic-entries" tabindex="-1">Too Many Traffic Entries <a class="header-anchor" href="#too-many-traffic-entries" aria-label="Permalink to &quot;Too Many Traffic Entries&quot;">​</a></h3><p>The most common cause of a slow UI is having too many entries in the traffic list. While the traffic list uses a virtualized renderer that can handle thousands of entries efficiently, extremely large lists (10,000+ entries) can still impact performance, especially on lower-powered machines.</p><p><strong>Solutions:</strong></p><ol><li><p><strong>Clear old traffic.</strong> Click the <strong>trash icon</strong> in the header toolbar to clear the current session&#39;s traffic. This immediately frees memory and improves responsiveness.</p></li><li><p><strong>Use sessions to organize.</strong> Create new sessions for different debugging tasks instead of capturing everything in one session. Smaller sessions are faster to load and browse.</p></li><li><p><strong>Pause recording</strong> when you do not need to capture traffic. Click the <strong>pause button</strong> in the header to stop recording while keeping the proxy active.</p></li><li><p><strong>Filter the traffic list.</strong> Use the filter bar to narrow down the displayed entries. Filtered views render fewer DOM elements and are faster.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start a new session at the beginning of each debugging task. This keeps each session focused and manageable. You can always switch back to older sessions to review historical data.</p></div><h3 id="browser-tab-memory" tabindex="-1">Browser Tab Memory <a class="header-anchor" href="#browser-tab-memory" aria-label="Permalink to &quot;Browser Tab Memory&quot;">​</a></h3><p>Each traffic entry consumes memory in the browser tab. Large response bodies (images, large JSON payloads) are particularly memory-intensive.</p><p><strong>Solutions:</strong></p><ul><li>Close and reopen the NectoProxy tab periodically to release accumulated memory.</li><li>Use a dedicated browser profile for NectoProxy so memory from other tabs does not compound.</li></ul><hr><h2 id="high-memory-usage" tabindex="-1">High Memory Usage <a class="header-anchor" href="#high-memory-usage" aria-label="Permalink to &quot;High Memory Usage&quot;">​</a></h2><p><strong>Symptom:</strong> The NectoProxy process (Node.js) uses a large amount of system memory.</p><h3 id="large-response-bodies" tabindex="-1">Large Response Bodies <a class="header-anchor" href="#large-response-bodies" aria-label="Permalink to &quot;Large Response Bodies&quot;">​</a></h3><p>NectoProxy stores request and response bodies in memory before writing them to the database. Large downloads, images, video, or API responses with massive payloads increase memory usage.</p><p><strong>Solutions:</strong></p><ol><li><p><strong>Reduce <code>maxBodySize</code>.</strong> Lower the maximum captured body size to limit memory consumption per entry:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reduce to 2 MB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/maxBodySize</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: 2097152}&#39;</span></span></code></pre></div></li><li><p><strong>Use SSL Passthrough</strong> for domains that serve large binary content you do not need to inspect (e.g., CDNs, video streaming, large file downloads):</p><p>In Settings &gt; SSL Passthrough, add domains like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.cdn.example.com</span></span>
<span class="line"><span>*.video.example.com</span></span></code></pre></div></li><li><p><strong>Block unnecessary traffic</strong> using Block rules for domains that generate high-volume traffic you do not care about (analytics, tracking, ads).</p></li></ol><h3 id="many-concurrent-connections" tabindex="-1">Many Concurrent Connections <a class="header-anchor" href="#many-concurrent-connections" aria-label="Permalink to &quot;Many Concurrent Connections&quot;">​</a></h3><p>If your application opens many simultaneous connections, NectoProxy manages all of them concurrently. This is normal but increases memory usage proportionally.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Monitor NectoProxy&#39;s memory usage with your system&#39;s activity monitor. On macOS, use Activity Monitor; on Linux, use <code>htop</code> or <code>top</code>; on Windows, use Task Manager.</p></div><hr><h2 id="database-growing-large" tabindex="-1">Database Growing Large <a class="header-anchor" href="#database-growing-large" aria-label="Permalink to &quot;Database Growing Large&quot;">​</a></h2><p><strong>Symptom:</strong> The <code>~/.nectoproxy/data.db</code> file is consuming significant disk space.</p><h3 id="check-database-size" tabindex="-1">Check Database Size <a class="header-anchor" href="#check-database-size" aria-label="Permalink to &quot;Check Database Size&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the file size</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On macOS / Linux, human-readable size</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span></span></code></pre></div><h3 id="reduce-database-size" tabindex="-1">Reduce Database Size <a class="header-anchor" href="#reduce-database-size" aria-label="Permalink to &quot;Reduce Database Size&quot;">​</a></h3><p><strong>1. Delete old sessions</strong></p><p>The most effective way to reclaim space. Each session contains all its traffic entries, WebSocket frames, and annotations. Deleting a session cascades to remove all associated data.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List sessions to find old ones</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete a session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Or use the Web UI: open the Sessions panel and delete sessions you no longer need.</p><p><strong>2. Compact the database</strong></p><p>After deleting data, SQLite may not immediately release disk space. Run <code>VACUUM</code> to compact:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;VACUUM;&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>VACUUM</code> requires temporary disk space equal to the size of the database. Ensure you have sufficient free disk space before running it. Also, stop NectoProxy before running <code>VACUUM</code> to avoid locking conflicts.</p></div><p><strong>3. Reduce <code>maxBodySize</code></strong></p><p>Smaller body size limits mean less data stored per entry. If you are mainly debugging headers and status codes, you can reduce this significantly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reduce to 1 MB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/maxBodySize</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: 1048576}&#39;</span></span></code></pre></div><p><strong>4. Start fresh</strong></p><p>If you do not need any historical data, delete the database and start over:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop NectoProxy first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>A new empty database is created automatically.</p><h3 id="recommended-database-size-limits" tabindex="-1">Recommended Database Size Limits <a class="header-anchor" href="#recommended-database-size-limits" aria-label="Permalink to &quot;Recommended Database Size Limits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Usage Pattern</th><th style="text-align:center;">Expected DB Size</th><th>Action</th></tr></thead><tbody><tr><td>Light (few sessions, small payloads)</td><td style="text-align:center;">&lt; 100 MB</td><td>No action needed</td></tr><tr><td>Moderate (daily use, medium payloads)</td><td style="text-align:center;">100 MB - 500 MB</td><td>Delete old sessions periodically</td></tr><tr><td>Heavy (continuous capture, large payloads)</td><td style="text-align:center;">500 MB - 1 GB</td><td>Reduce maxBodySize, delete sessions weekly</td></tr><tr><td>Excessive</td><td style="text-align:center;">&gt; 1 GB</td><td>VACUUM, review maxBodySize, clean up</td></tr></tbody></table><hr><h2 id="proxy-adds-latency" tabindex="-1">Proxy Adds Latency <a class="header-anchor" href="#proxy-adds-latency" aria-label="Permalink to &quot;Proxy Adds Latency&quot;">​</a></h2><p><strong>Symptom:</strong> Requests are noticeably slower when going through NectoProxy compared to direct connections.</p><p><strong>Explanation:</strong> Some latency is inherent in any MITM (man-in-the-middle) proxy. For HTTPS connections, NectoProxy performs the following additional operations:</p><ol><li>Terminates the client&#39;s TLS connection.</li><li>Generates (or retrieves from cache) a certificate for the target domain.</li><li>Decrypts the request.</li><li>Establishes a new TLS connection to the target server.</li><li>Forwards the request.</li><li>Receives the response.</li><li>Stores the data in the database.</li><li>Encrypts and forwards the response to the client.</li></ol><h3 id="reducing-proxy-latency" tabindex="-1">Reducing Proxy Latency <a class="header-anchor" href="#reducing-proxy-latency" aria-label="Permalink to &quot;Reducing Proxy Latency&quot;">​</a></h3><p><strong>1. Use SSL Passthrough for non-debugged domains</strong></p><p>Domains in the SSL Passthrough list bypass the MITM process entirely. The TLS connection is tunneled directly without decryption, adding minimal latency:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.googleapis.com</span></span>
<span class="line"><span>*.gstatic.com</span></span>
<span class="line"><span>*.cloudflare.com</span></span>
<span class="line"><span>fonts.googleapis.com</span></span></code></pre></div><p>This is the single most effective way to reduce latency for domains you are not debugging.</p><p><strong>2. Certificate caching</strong></p><p>NectoProxy caches generated domain certificates automatically. The first request to a new domain has slightly higher latency due to certificate generation; subsequent requests use the cached certificate.</p><p><strong>3. Database write performance</strong></p><p>NectoProxy uses SQLite with WAL mode, which provides good concurrent write performance. Database writes happen asynchronously (fire-and-forget) and should not block request processing.</p><hr><h2 id="virtualized-list-performance" tabindex="-1">Virtualized List Performance <a class="header-anchor" href="#virtualized-list-performance" aria-label="Permalink to &quot;Virtualized List Performance&quot;">​</a></h2><p>NectoProxy&#39;s traffic list uses a virtualized renderer, which means only the visible rows are rendered in the DOM. This architecture provides good performance even with thousands of entries.</p><p>If you experience scrolling issues:</p><ol><li><strong>Reduce the number of entries</strong> by using filters or starting a new session.</li><li><strong>Avoid extremely wide layouts</strong> that cause horizontal scrolling in the detail panel.</li><li><strong>Close the detail panel</strong> when scrolling through the traffic list to reduce rendering load.</li><li><strong>Use a modern browser.</strong> Chrome and Edge generally provide the best rendering performance for large lists.</li></ol>`,65)])])}const u=s(n,[["render",o]]);export{g as __pageData,u as default};
